    unsafe extern "system" fn(
        *mut HANDLE,
        u32,
        *mut std::ffi::c_void, // OBJECT_ATTRIBUTES*
        *mut std::ffi::c_void, // IO_STATUS_BLOCK*
        *const i64,            // LARGE_INTEGER*
        u32,
        u32,
        u32,
